package com.nextfeet.nextfeet.model; public class Categoria { private Integer id; private String nombre,descripcion,estado; public Categoria(){} public Categoria(Integer id,String nombre,String descripcion,String estado){this.id=id;this.nombre=nombre;this.descripcion=descripcion;this.estado=estado;} public Integer getId(){return id;} public void setId(Integer v){id=v;} public String getNombre(){return nombre;} public void setNombre(String v){nombre=v;} public String getDescripcion(){return descripcion;} public void setDescripcion(String v){descripcion=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} }